                <span style="background: var(--light); padding: 0.5rem 1rem; border-radius: 20px; font-size: 0.9rem;">Aged (1,969)</span>
                <span style="background: var(--light); padding: 0.5rem 1rem; border-radius: 20px; font-size: 0.9rem;">Mice (1,743)</span>
                <span style="background: var(--light); padding: 0.5rem 1rem; border-radius: 20px; font-size: 0.9rem;">COVID-19 (902)</span>
            </div>
        </div>

        <!-- Section 4: Open Access Patterns -->
        <div class="section">
            <h2>Open Access Adoption & Journal Landscape</h2>

            <div class="chart-container">
                <canvas id="oaTrendChart"></canvas>
            </div>

            <h3>Open Access Rate by Year</h3>
            <div class="chart-row-3" style="margin: 1.5rem 0;">
                <div style="text-align: center; padding: 1.5rem; background: var(--light); border-radius: 8px;">
                    <div style="font-size: 2rem; font-weight: 700; color: var(--primary);">64.1%</div>
                    <div style="color: var(--muted);">2024</div>
                </div>
                <div style="text-align: center; padding: 1.5rem; background: var(--light); border-radius: 8px;">
                    <div style="font-size: 2rem; font-weight: 700; color: var(--success);">74.1%</div>
                    <div style="color: var(--muted);">2025</div>
                    <div style="font-size: 0.8rem; color: var(--success);">+10.0pp</div>
                </div>
