        <div class="section">
            <h2>Research Type Distribution & Collaboration Indicators</h2>

            <div class="chart-row">
                <div class="chart-container">
                    <canvas id="typeChart"></canvas>
                </div>
                <div class="chart-container">
                    <canvas id="typeYearChart"></canvas>
                </div>
