            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { position: 'top' }, title: { display: true, text: 'Monthly Publication Volume by Year' } },
                scales: { y: { beginAtZero: true, title: { display: true, text: 'Publications' } } }
            }
        });

        // Country Chart
        const countryCtx = document.getElementById('countryChart').getContext('2d');
        new Chart(countryCtx, {
            type: 'doughnut',
            data: {
                labels: ['China', 'USA', 'India', 'Japan', 'Iran', 'Canada', 'Germany', 'Italy', 'UK', 'Australia', 'Other'],
                datasets: [{
                    data: [952, 415, 196, 137, 107, 107, 98, 89, 78, 65].map(v => Math.round(v * scaleFactor)).concat([2537].map(v => Math.round(v * scaleFactor))),
                    backgroundColor: ['#1a365d', '#2c5282', '#3182ce', '#4299e1', '#63b3ed', '#90cdf4', '#bee3f8', '#2b6cb0', '#2c5282', '#3182ce', '#a0aec0']
                }]
            },
            options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'right' }, title: { display: true, text: 'Top 10 Countries' } } }
        });

        // Topic Chart
        const topicCtx = document.getElementById('topicChart').getContext('2d');
